function draw(time=performance.now()) {
  const m=map(); if (!m) return;
  ctx.clearRect(0,0,canvas.width,canvas.height);
  for(let y=0;y<m.height;y++) for(let x=0;x<m.width;x++) tileDraw(m.tiles[y][x],x,y,time);
